def build_agent(sandbox):
    # Create a simple agent body with moderate density for responsiveness
    agent = sandbox.add_box(x=0.5, y=1.95, width=0.4, height=0.4, density=1.0)
    return agent

def agent_action(sandbox, agent_body, step_count):
    pos = sandbox.get_agent_position()
    vel = sandbox.get_agent_velocity()
    next_sw = sandbox.get_next_required_switch()
    steps_in = sandbox.get_steps_in_current_zone()
    need = sandbox.get_steps_required_to_trigger()
    cooldown = sandbox.get_cooldown_remaining()
    triggered_switches = sandbox.get_triggered_switches()

    if next_sw is None:
        return  # Sequence complete

    # Handle cooldown period
    if cooldown > 0:
        sandbox.apply_agent_force(0, 0)
        return

    in_correct_zone = False
    target_pos = None

    # Determine target based on next required switch
    if next_sw == 'A':
        # Zone A: (2.0, 2.0), half-width 0.5, half-height 0.5
        x, y = pos
        if 1.5 <= x <= 2.5 and 1.5 <= y <= 2.5:
            in_correct_zone = True
        else:
            target_pos = (2.0, 2.0)
    elif next_sw == 'B':
        # Zone B: (4.95, 3.2), half-width 0.7, half-height 0.4
        x, y = pos
        if 4.25 <= x <= 5.65 and 2.8 <= y <= 3.6:
            in_correct_zone = True
        else:
            # Ensure A is triggered and barrier is open
            if 'A' in triggered_switches:
                barrier_delay = sandbox.get_barrier_delay_steps()
                if barrier_delay <= 0:
                    target_pos = (4.95, 3.2)
    elif next_sw == 'C':
        # Zone C: (8.0, 2.0), half-width 0.5, half-height 0.5
        x, y = pos
        if 7.5 <= x <= 8.5 and 1.5 <= y <= 2.5:
            in_correct_zone = True
        else:
            if 'B' in triggered_switches:
                # Assume altitude requirement is met if B was triggered
                target_pos = (8.0, 2.0)

    # If in correct zone, ensure velocity and force constraints
    if in_correct_zone:
        speed = (vel[0]**2 + vel[1]**2)**0.5
        if speed > 0.08:
            # Exceed speed limit - reset progress
            sandbox.apply_agent_force(0, 0)
        else:
            # Apply zero force to maintain position
            sandbox.apply_agent_force(0, 0)
            if steps_in >= need:
                # Trigger is already handled by environment
                pass
    else:
        # Target position is defined
        if target_pos is not None:
            dx = target_pos[0] - pos[0]
            dy = target_pos[1] - pos[1]
            distance = (dx**2 + dy**2)**0.5
            if distance > 0.01:
                dir_x = dx / distance
                dir_y = dy / distance

                # Proportional force control with safety limits
                force = 10.0  # Base force magnitude
                fx = dir_x * force
                fy = dir_y * force

                # Clamp to max force limit (50 N per axis)
                fx = max(min(fx, 50), -50)
                fy = max(min(fy, 50), -50)

                sandbox.apply_agent_force(fx, fy)
            else:
                # Already at target
                sandbox.apply_agent_force(0, 0)
        else:
            # No valid target, stay still
            sandbox.apply_agent_force(0, 0)
